def add_body(doc, text):
    p = doc.add_paragraph(text)
    p.paragraph_format.space_after = Pt(8)
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    return p

def build(uni, lang):
    path, key, uname, prog_es, prog_en, is_upm = uni
    es = (lang == "ES")
    doc = Document()
    # Encabezado
    h = doc.add_paragraph()
    r = h.add_run("PROPUESTA DE INVESTIGACIÓN" if es else "RESEARCH PROPOSAL")
    r.bold = True; r.font.size = Pt(14)
    h.alignment = WD_ALIGN_PARAGRAPH.CENTER
    sub = doc.add_paragraph()
    sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
    sub.add_run(uname + "\n").bold = True
    sub.add_run((prog_es if es else prog_en) + "\n")
    sub.add_run(("Proponente: " if es else "Applicant: ") + AUTOR)
    doc.add_paragraph()
    # 1
    doc.add_heading("1. Título provisional y palabras clave" if es else "1. Working title and keywords", level=1)
    p = doc.add_paragraph(); p.add_run(("Título: " if es else "Title: ")).bold = True
    p.add_run(TITULO_ES if es else TITULO_EN)
    p = doc.add_paragraph(); p.add_run(("Pregunta de investigación: " if es else "Research question: ")).bold = True
    p.add_run(PREGUNTA_ES if es else PREGUNTA_EN)
    p = doc.add_paragraph(); p.add_run(("Palabras clave: " if es else "Keywords: ")).bold = True
    p.add_run(KW_ES if es else KW_EN)
    # 2
    doc.add_heading("2. Planteamiento del problema y justificación" if es else "2. Problem statement and justification", level=1)
    for t in (SEC2_ES if es else SEC2_EN): add_body(doc, t)
    # 3 (núcleo + encaje)
    doc.add_heading("3. Estado del arte y encuadre teórico" if es else "3. State of the art and theoretical framework", level=1)
    for t in (SEC3_ES if es else SEC3_EN): add_body(doc, t)
    add_body(doc, ENC[key][0 if es else 1])
    # 4
    doc.add_heading("4. Orientación metodológica" if es else "4. Methodological approach", level=1)
    for t in (SEC4_ES if es else SEC4_EN): add_body(doc, t)
    # 5
    doc.add_heading("5. Referencias" if es else "5. References", level=1)
    refs = list(REFS_CORE) + (REFS_UPM_EXTRA if is_upm else [])
    refs.sort(key=lambda s: s.lower())
    for ref in refs:
        rp = doc.add_paragraph(ref)
        rp.paragraph_format.left_indent = Pt(18)
        rp.paragraph_format.first_line_indent = Pt(-18)
        rp.paragraph_format.space_after = Pt(4)
    fn = "Propuesta_GDA_ES.docx" if es else "Research_Proposal_GDA_EN.docx"
    out = os.path.join(path, fn)
    doc.save(out)
    return out

count = 0
for uni in UNIS:
    for lang in ("ES", "EN"):
        if not os.path.isdir(uni[0]):
            print("FALTA CARPETA:", uni[0]); continue
        out = build(uni, lang)
        count += 1
        print("OK", os.path.relpath(out, ROOT))
print("\nTOTAL DOCUMENTOS:", count)
